mk('h25a','o25','Opdracht 25a','Waar gaat de expeditie naartoe? Welk tekstelement uit de derde alinea (r. 19–27) laat dat zien?','εἰς τὴν Κολχίδα (r. 22–23)',['κατὰ θάλατταν (r. 22)','εἰς τὴν Ἑλλάδα (r. 24)','ἐν τῷ λιμένι (r. 3)'],'Naar Kolchis: οἴσει δ’ ἡμᾶς ἡ Ἀργὼ … εἰς τὴν Κολχίδα. εἰς τὴν Ἑλλάδα is de terugweg met het vlies.','Waar brengt de Argo de helden naartoe? Noem het tekstelement.');
mk('h25b','o25','Opdracht 25b','Vergelijk r. 9–10 met r. 25–27. Welk kenmerk van de expeditie wordt twee keer met een tegenstelling beschreven?','Het is een gevaarlijke expeditie',['Het is een lange reis over zee','Het is een expeditie van goden','Het is een geheime opdracht'],'r. 9–10: κίνδυνοι πολλοί ↔ οὐδεὶς φόβῳ ἄπεστιν; r. 25–27: κίνδυνοι μὲν πολλοί ↔ ἀλλὰ καὶ μεγάλην τιμήν.','Welk kenmerk van de tocht komt in r. 9–10 en r. 25–27 terug?');
op('h25bc','o25','Opdracht 25b','Noteer de twee tegenstellingen uit r. 9–10 en r. 25–27.',['r. 9–10: vele gevaren (κίνδυνοι πολλοί) ↔ niemand is uit angst afwezig (οὐδεὶς φόβῳ ἄπεστιν)','r. 25–27: vele gevaren (κίνδυνοι μὲν πολλοί) ↔ maar ook grote eer (ἀλλὰ καὶ μεγάλην τιμήν)'],
  'Gevaren tegenover geen angst (r. 9–10), en gevaren tegenover grote eer (r. 25–27).','Welke tegenstellingen staan in r. 9–10 en in r. 25–27?');
op('h25c','o25','Opdracht 25c','Leg uit dat dit kenmerk past bij het gedrag van Griekse helden.',['Griekse helden zoeken het gevaar op','Daarmee verdienen ze eer en roem (τιμή)','Eer is voor een held belangrijker dan veiligheid'],'Griekse helden gaan het gevaar niet uit de weg: juist door gevaar te trotseren verdienen ze eer (τιμή), en die eer is voor hen het belangrijkste.','Waarom past een gevaarlijke tocht bij een Griekse held?');
mk('h26c','o26','Opdracht 26c','De rol van Iason ligt al vast. Welk tekstelement uit r. 1–8 noemt die rol?','ὁ τοῦ στόλου ἡγεμών (r. 8)',['ὁ ναυπηγός (r. 3)','τοὺς τῆς Ἑλλάδος ἥρωας (r. 1)','τὸ ἔργον αὐτοῦ (r. 4)'],'Iason is de leider van de expeditie.','Wat is de rol van Iason volgens r. 8?');
[['Βορεάδαι','gevleugeld en ze willen hun moed tonen (r. 11–12)'],['Ὀρφεύς','betovert met zijn liederen mensen, dieren en bomen (r. 13–15)'],['Ἀταλάντη','overtreft met de boog altijd de mannen (r. 16–17)'],['Ἄργος','scheepsbouwer: hij bouwt de Argo, met hulp van Athena (r. 3, 19–21)']].forEach(([n,e],i,all)=>
  mk('h26'+i,'o26','Opdracht 26a/b',`Welke eigenschap past bij ${n}?`,e,all.filter(x=>x[0]!==n).map(x=>x[1]),`${n}: ${e}.`,`${n} in tekst 8: wat is zijn of haar eigenschap?`));

/* Hulpboek les 9, opdracht 28–30 en 34 (p. 38–39; tekstboek p. 46) */
sec('o28','hb9','28','Opdracht 28: fout en straf','--c1','HB p. 38 · tekstboek p. 46',[['Lemnos','De vrouwen vergaten aan Aphrodite te offeren',''],['Phineus','Hij maakte de toekomst bekend aan de hele mensheid','']]);
sec('o29','hb9','29','Opdracht 29: ik doe wat voor jou …','--c2','HB p. 38',[['Principe','Ik doe wat voor jou als jij wat voor mij doet','']]);
sec('o30','hb9','30','Opdracht 30: naamvallen en functie','--c6','HB p. 38 · r. 1–12',[['Dativus en genitivus','-ῳ, -ᾳ, -ῃ, -οις = dat · -ου, -ης, -ων = gen',''],['Functie','dat: meewerkend voorwerp of bijwoordelijke bepaling · gen: bijvoeglijke bepaling (van …) of na een voorzetsel','']]);
sec('o34','hb9','34','Opdracht 34: de weggelaten woorden','--c3','HB p. 39 · r. 20–29',[['Werkwijze','Zoek in de Griekse tekst het woord dat op die plek hoort en geef de vertaling','']]);
op('h28a','o28','Opdracht 28a','Is er volgens jou een verband tussen de fout en de straf bij de vrouwen van Lemnos? Licht toe.',['Fout: ze vergaten aan Aphrodite te offeren','Straf: Aphrodite zorgde dat hun mannen niet meer in hen geïnteresseerd waren','Verband: Aphrodite is de godin van de liefde, dus ze worden gestraft in de liefde'],
  'Ja. Ze vergaten te offeren aan Aphrodite, de godin van de liefde, en Aphrodite strafte hen juist in de liefde: hun mannen wilden niets meer van hen weten.','Wat was de fout van de vrouwen van Lemnos, wat de straf, en hoort dat bij elkaar?');
op('h28b','o28','Opdracht 28b','Is er volgens jou een verband tussen fout en straf bij Phineus? Betrek beide straffen in je antwoord.',['Fout: hij maakte de toekomst (een gave van Apollo) aan de hele mensheid bekend','Straf 1: Zeus maakte hem blind','Straf 2: de Harpijen roven en bederven zijn eten','Verband: hij liet mensen te veel zien → hij kan zelf niets meer zien'],
  'Ja. Phineus liet de mensen te veel zien van de toekomst; daarom maakte Zeus hem blind. En de Harpijen nemen hem steeds zijn eten af, zodat hij net als de toekomst die hij weggaf zelf niets meer houdt.','Waarom werd Phineus gestraft, hoe, en past de straf bij de fout?');
op('h28c','o28','Opdracht 28c','Vind je dat er zowel bij de vrouwen van Lemnos als bij Phineus sprake is van hybris? Licht toe.',['Hybris: een mens stelt zich boven de goden (les 6, proloog)','Phineus: ja, hij gaf kennis van de goden aan alle mensen','Lemnos: vergeten te offeren is eerder nalatigheid dan hoogmoed; jij beslist','Geef bij allebei een eigen oordeel met een reden'],
  'Bij Phineus wel: hij deelde kennis die alleen voor de goden was met alle mensen, alsof hij boven de goden stond. Bij de vrouwen van Lemnos minder: ze vergaten te offeren, dat is eerder nalatig dan hoogmoedig.','Is er sprake van hybris bij Phineus en bij de vrouwen van Lemnos?');
op('h29a','o29','Opdracht 29a','Leg uit dat het principe "ik doe wat voor jou als jij wat voor mij doet" ook speelt bij de verering van de goden.',['Mensen offeren aan de goden','In ruil helpen de goden hen','Wie niet offert, krijgt geen hulp of wordt gestraft (Lemnos)'],
  'Mensen brengen offers aan de goden, en in ruil verwachten ze hulp of bescherming. Wie vergeet te offeren, wordt gestraft, zoals de vrouwen van Lemnos.','Hoe werkt "ik doe wat voor jou als jij wat voor mij doet" tussen mensen en goden?');
mk('h29b','o29','Opdracht 29b','Welke rol speelt dit principe in de ontmoeting van de Argonauten met Phineus?','Phineus helpt met advies als de Argonauten hem eerst van de Harpijen verlossen',['Phineus geeft goud als de Argonauten hem meenemen','De Argonauten offeren aan Zeus voor Phineus','Phineus helpt zonder iets terug te vragen'],'εἰ πρῶτον οἱ ἥρωες βοηθεῖν ἐθέλουσιν αὐτῷ (r. 4–5).','Wat moeten de Argonauten eerst doen voordat Phineus helpt?');
op('h30a','o30','Opdracht 30a','Noteer en vertaal uit r. 1–12 drie zelfstandig naamwoorden in de dativus en drie in de genitivus.',['Dativus: τῇ χώρᾳ (r. 1, het gebied), τῷ γέροντι (r. 7–8, de oude man), φόβῳ (r. 11, angst)','Genitivus: τοῦ στόλου (r. 3, de expeditie), τῶν κινδύνων (r. 3, de gevaren), τῶν θεῶν (r. 6, de goden), τῆς χώρας (r. 11, het gebied)'],
  'Dativus: τῇ χώρᾳ (gebied), τῷ γέροντι (oude man), φόβῳ (angst). Genitivus: τοῦ στόλου (expeditie), τῶν κινδύνων (gevaren), τῶν θεῶν (goden).','Zoek in r. 1–12 drie dativi en drie genitivi en vertaal ze.');
[['ἐν τῇ χώρᾳ','r. 1','ev, vrl, bijwoordelijke bepaling (plaats)'],['τῷ γέροντι','r. 7–8','ev, mnl, meewerkend voorwerp'],['φόβῳ','r. 11','ev, mnl, bijwoordelijke bepaling (reden)'],['τοῦ στόλου','r. 3','ev, mnl, bijvoeglijke bepaling'],['τῶν θεῶν','r. 6','mv, mnl, bijvoeglijke bepaling'],['περὶ τῶν κινδύνων','r. 3','mv, mnl, bijwoordelijke bepaling (na περί)']].forEach(([w,r,a],i,all)=>
  mk('h30'+i,'o30','Opdracht 30b/c',`${w} (${r}): welk getal, welk geslacht en welke functie?`,a,all.filter(x=>x[2]!==a).map(x=>x[2]).concat(['mv, vrl, lijdend voorwerp']).slice(0,3),`${w}: ${a}.`,`Getal, geslacht en functie van ${w} (${r})?`));
[['De Argonauten sturen eerst [1] door de Symplegaden','πέλειαν','een duif'],['… heen [2] de [3] van [4]','κατὰ τοὺς τοῦ γέροντος λόγους','overeenkomstig de woorden van de oude man'],['De Symplegaden [5], maar de duif is sneller','συγκροτοῦσι','klappen tegen elkaar'],
 ['[6] vernietigen alleen maar een stukje [7]','αἱ πέτραι … τοῦ ὀρροπυγίου','de rotsen … van de staart'],['[8] roeien [9] zo snel mogelijk','Αὐτίκα … οἱ ἥρωες','meteen … de helden'],['Opnieuw klappen de rotsen tegen elkaar, maar ze vernietigen alleen een stukje …','τῆς πρύμνης','van de achtersteven'],
 ['Zo is vanaf nu [13] [14] Kolchis vrij','ἡ … ὁδὸς … εἰς τὴν Κολχίδα','de weg naar Kolchis'],['… vrij [15] en [16]','τῷ πλοίῳ καὶ τοῖς ἥρωσιν','voor het schip en de helden']].forEach(([zin,gr,nl],i,all)=>
  mk('h34'+i,'o34','Opdracht 34',`Opdracht 34: <i>${zin}</i><br>Welke Griekse woorden horen op de open plek, en wat is de vertaling?`,`${gr}: ${nl}`,all.filter(x=>x[1]!==gr).map(x=>`${x[1]}: ${x[2]}`).slice(0,3),`${gr} = ${nl}.`,`Zoek in r. 20–29 de woorden voor <i>${zin}</i>.`));

