sec('o40','hb10','40','Opdracht 40: Grieks en twee vertalingen','--c4','HB p. 40 · Argonautika 4, 149–155',[['A = Grieks, B = vertaling Kassies, C = bewerking Kegel','Αἰσονίδης r. 149 · μυρία κύκλα r. 151 · σμερδαλέην κεφαλήν r. 154','']]);
