op('h37','o37','Opdracht 37','Zowel Pelias (les 8) als Aietes reageren op dezelfde manier wanneer Iason vertelt wat het doel van zijn komst is. Leg dit uit.',['Allebei geven ze hem een (bijna) onmogelijke opdracht','Pelias: eerst het Gulden Vlies halen, dan mag hij koning worden','Aietes: eerst de vuurspuwende ossen temmen, het veld ploegen, drakentanden zaaien en de gewapende mannen verslaan','Ze hopen allebei dat het hem niet lukt, zodat ze houden wat ze hebben (troon, vlies)'],
  'Ze zeggen allebei "ja, maar eerst …" en geven hem een bijna onmogelijke opdracht. Pelias wil zijn troon houden en stuurt Iason om het Gulden Vlies; Aietes wil het vlies houden en laat hem eerst vuurspuwende ossen temmen, drakentanden zaaien en de gewapende mannen verslaan. Ze hopen dat Iason daarbij omkomt.',
  'Wat doen Pelias en Aietes allebei als Iason zegt wat hij wil?');
mk('h37b','o37','Opdracht 37','Wat moet Iason van Aietes eerst doen voordat hij het Gulden Vlies krijgt?','Vuurspuwende ossen temmen, een veld ploegen, drakentanden zaaien en de gewapende mannen verslaan',['De draak in slaap zingen','Zijn oom Pelias verslaan','Medea trouwen en in Kolchis blijven'],'Zo staat het in de inleiding van les 10 (tekstboek p. 48).','Welke opdracht krijgt Iason van Aietes?');
[['Hera','Ze draagt Iason een warm hart toe en zorgt dat Eros een pijl afschiet op Medea'],['Eros','Hij schiet een gouden pijl af op Medea, zodat ze verliefd wordt op Iason'],['de Slaap (Hypnos)','Medea roept hem aan om het beest te betoveren, zodat de draak in slaap valt'],['Hekate','Medea roept haar aan, de godin uit de onderwereld die ’s nachts rondzwerft, om haar te helpen bij haar aanval']].forEach(([n,h],i,all)=>
  mk('h38'+i,'o38','Opdracht 38',`Hoe helpt ${n} bij de missie van Iason?`,h,all.filter(x=>x[0]!==n).map(x=>x[1]),`${n}: ${h.toLowerCase()}.`,`Wat doet ${n} in les 10?`));
op('h39','o39','Opdracht 39','In de tekst worden drie kenmerken genoemd die de draak gevaarlijk maken. Noteer de tekstelementen.',['Hij slaapt nooit (de nooit slapende draak, inleiding)','Hij is enorm lang, met ontelbare kronkels/windingen (μυρία κύκλα)','Hij heeft een angstaanjagende kop met dodelijke kaken (σμερδαλέην κεφαλήν)','Ook mogelijk: bedekt met harde schubben'],
  'De draak slaapt nooit; hij heeft ontelbare kronkels (μυρία κύκλα); en hij heeft een angstaanjagende kop met dodelijke kaken (σμερδαλέην κεφαλήν).','Welke drie dingen maken de draak gevaarlijk? Noem de tekstelementen.');
[['Αἰσονίδης','r. 149','de zoon van Aison (Iason)','B: Iason · C: de zoon van Aison'],['μυρία κύκλα','r. 151','ontelbare kronkels','B: ontelbare windingen · C: ontelbare cirkels'],['σμερδαλέην κεφαλήν','r. 154','de angstaanjagende kop','B: zijn vreselijke kop · C: zijn angstaanjagende hoofd']].forEach(([w,r,a,u],i,all)=>
  mk('h40'+i,'o40','Opdracht 40a',`Wat betekent ${w} (${r})?`,a,all.filter(x=>x[0]!==w).map(x=>x[2]).concat(['het gouden vlies']),`${w} = ${a}. ${u}.`,`Hoe geven de vertalers ${w} weer?`));
mk('h40b','o40','Opdracht 40b','ὁ δράκων betekent slang of draak. Welk woord gebruiken de twee Nederlandse teksten?','B (Kassies): slang · C (Kegel): draak',['B: draak · C: slang','Allebei: slang','Allebei: monster'],'Tekst B: "De slang liet al …"; tekst C: "maar de draak was al door het lied betoverd".','Hoe noemt vertaling B het beest, en hoe bewerking C?');
op('h40c','o40','Opdracht 40c','Welke vertaling vind jij het best passen bij de beschrijving? Beargumenteer je antwoord.',['Geen vast antwoord','Kijk naar ontelbare kronkels, lang lijf, kop: past dat bij een slang of een draak?','Noem een tekstelement als argument'],
  'Bijvoorbeeld: "draak" (C), want het beest heeft een angstaanjagende kop, dodelijke kaken en harde schubben en bewaakt een schat: dat past bij een draak. Maar "slang" (B) past bij het lange, kronkelende lijf.','Slang of draak: wat vind jij het beste, en waarom?');
op('h41','o41','Opdracht 41','Bekijk de afbeelding op p. 49 (middeleeuws Frans manuscript). Welke elementen en/of personages uit de mythe van Iason en het Gulden Vlies herken je? In hoeverre vind je de afbeelding passend?',['De Argo (het schip met de bemanning)','Iason in harnas die vecht','De vuurspuwende ossen/stieren','De draak','Gewapende mannen (uit de drakentanden)','Passend? Let op: middeleeuwse ridders in harnas, dat past niet bij de Griekse tijd'],
  'Ik zie de Argo met de Argonauten, Iason als ridder die vecht met een vuurspuwend beest (de ossen van Aietes), gewapende mannen en de draak. Passend omdat er veel delen van de mythe in één beeld staan; minder passend omdat iedereen in een middeleeuws harnas zit.','Wat herken je op de afbeelding op p. 49, en past het bij het verhaal?');
[['hier is het Gulden Vlies (2 hor.)','Kolchis'],['tweelingbroer van Kastor (6 hor.)','Polydeukes'],['beste zanger (7 hor.)','Orpheus'],['tovenares die Iason helpt (10 hor.)','Medea'],['enige vrouw aan boord van de Argo (12 hor.)','Atalante'],['blinde koning (14 hor.)','Phineus'],
 ['monster dat Phineus kwelt (1 vert.)','Harpij'],['vertrekhaven van de Argo (3 vert.)','Iolkos'],['leider van de Argonauten (4 vert.)','Iason'],['samenklappende rotsen (5 vert.)','Symplegaden'],['eiland waar de Argo aanmeert (8 vert.)','Lemnos'],['bekend om zijn enorme kracht (9 vert.)','Herakles'],['schip waarvan Tiphys stuurman is (11 vert.)','Argo'],['een zoon van de Noordenwind (13 hor.)','een van de Boreaden (Zetes of Kalaïs)']].forEach(([v,a],i,all)=>
  mk('h42'+i,'o42','Opdracht 42',`Puzzel: ${v}`,a,shuf(all.filter(x=>x[1]!==a).map(x=>x[1])).slice(0,3),`${v}: ${a}.`,`Wie of wat is: ${v}?`));

