sec('o43','epi','43','Opdracht 43: wat maakt een held?','--c1','HB p. 42',[['Herakles','bovenmenselijke kracht en slimheid',''],['Superhelden','bijzondere krachten, onwaarschijnlijke daden','']]);
sec('o44','epi','44','Opdracht 44: de twaalf werken','--c2','HB p. 42 · tekstboek p. 50 en afbeeldingen p. 43',[['Schema','opdracht · gevaarlijk aspect · eigenschap van Herakles','Nummer 12: Kerberos uit de onderwereld halen · driekoppige, bijtgrage hond · kracht en slimheid']]);
sec('o45','epi','45','Opdracht 45: ΗΡΑΚΛΗΣ cement','--c3','HB p. 42',[['Nieuwgrieks','ΤΣΙΜΕΝΤΟ = τσιμέντο = cement','']]);
sec('o46','epi','46','Opdracht 46: het vaste patroon','--c4','HB p. 44',[['Patroon (les 7)','vader · moeder · reden voor de heldendaad · held in actie · hulp','']]);
sec('o47','epi','47','Opdracht 47: Herakles of Iason?','--c5','HB p. 44',[['Beargumenteer','Kies een uitspraak en geef argumenten uit de verhalen','']]);
op('h43','o43','Opdracht 43','a Wat maakt iemand voor jou tot een held? b Welke eigenschappen maken Herakles tot een held? c Welke eigenschappen maken Spiderman of Superman tot helden? d Vergelijk de antwoorden bij a, b en c.',['a: je eigen eigenschappen (bijv. moed, anderen helpen)','b: zijn bovenmenselijke kracht en zijn slimheid','c: bijzondere krachten waarmee ze onmogelijke daden doen, en ze zetten die in voor anderen','d: noem een overeenkomst (bijzondere krachten) en een verschil'],
  'b: Herakles is een held door zijn bovenmenselijke kracht en zijn slimheid. c: Spiderman en Superman hebben bijzondere krachten en doen onwaarschijnlijke daden. d: Overeenkomst: bovenmenselijke krachten. Verschil: superhelden helpen anderen uit zichzelf; Herakles deed zijn opdrachten als straf.','Wat maakt Herakles en wat maakt Superman tot een held?');
mk('h43b','o43','Opdracht 43b','Welke combinatie maakt Herakles volgens het tekstboek tot de beroemdste held?','bovenmenselijke kracht en slimheid',['schoonheid en zangkunst','snelheid en vleugels','rijkdom en macht'],'Zijn combinatie van bovenmenselijke kracht en slimheid (tekstboek p. 50).','Waardoor is Herakles de beroemdste Griekse held?');
mk('h46a','o46','Opdracht 46a','Op welk punt wijkt het verhaal van Herakles het duidelijkst af van het vaste patroon?','De reden: hij doet de opdrachten als straf, omdat hij in een vlaag van waanzin zijn vrouw en kinderen doodde',['Hij krijgt geen enkele hulp','Hij heeft geen vader','Hij is geen held in actie'],'Anders dan Iason vervult Herakles zijn opdrachten niet als uitdaging, maar als straf (boetedoening). Hera, die hem haatte, zorgde voor de waanzin.','Waarom doet Herakles zijn twaalf werken, en waarom is dat anders dan bij Iason?');
op('h46b','o46','Opdracht 46b','Kies Mozes, Aragorn (Lord of the Rings) of Simba (The Lion King) en licht toe hoe je het vaste patroon in het verhaal herkent.',['Geen vast antwoord','Ga de vijf punten langs: vader, moeder, reden, held in actie, hulp','Simba lijkt erg op Iason: zijn oom (Scar) pakt de troon van zijn vader, Simba groeit ver weg op en komt terug'],
  'Bijvoorbeeld Simba: vader Mufasa is koning; zijn oom Scar doodt hem en pakt de troon (net als Pelias); Simba groeit ver weg op bij Timon en Pumbaa; hij keert terug en verslaat Scar (held in actie), met hulp van Nala en Rafiki.','Hoe zie je het patroon van het heldenverhaal bij Simba, Aragorn of Mozes?');
op('h47','o47','Opdracht 47','Herakles en Iason hebben allebei kenmerken die hen tot held maken. Met welke uitspraak ben je het eens: 1 Herakles is een grotere held dan Iason, of 2 Herakles en Iason zijn beiden even grote helden? Beargumenteer.',['Geen vast antwoord','Herakles: bovenmenselijke kracht, doet alles zelf','Iason: leider, maar heeft veel hulp nodig (Argonauten, Medea, goden)','Kies en geef minstens twee argumenten'],
  'Bijvoorbeeld 1: Herakles doet twaalf onmogelijke opdrachten met zijn eigen kracht en slimheid, terwijl Iason het zonder Medea en de goden niet had gered.','Wie is de grotere held, Herakles of Iason? Leg uit.');
[['een leeuw met een onkwetsbare huid','hij kon niet verwond worden','kracht (hij wurgde hem)'],['een negenkoppige slang (Hydra)','voor elke afgehakte kop kwamen er nieuwe','slimheid (de wonden dichtbranden)'],['de stallen van Augias schoonmaken','dertig jaar niet uitgemest, in één dag','slimheid (rivieren erdoor leiden)'],['de gordel van Hippolyte halen','zij was koningin van de krijgshaftige Amazonen','moed en kracht'],['gouden appels halen bij de Hesperiden','ze groeiden in een tuin in het uiterste westen','slimheid'],['Kerberos uit de onderwereld halen','driekoppige, bijtgrage hond','kracht en slimheid']].forEach(([o,gv,e],i,all)=>
  mk('h44'+i,'o44','Opdracht 44',`Twaalf werken: <b>${o}</b>. Wat was het gevaarlijke aspect?`,gv,all.filter(x=>x[0]!==o).map(x=>x[1]),`${o}: ${gv}. Eigenschap van Herakles: ${e}.`,`Wat maakte de opdracht "${o}" gevaarlijk?`));
op('h44s','o44','Opdracht 44','Neem het schema over: omschrijving van de opdracht, het gevaarlijke aspect en de eigenschap van Herakles. Noem er zoveel als je kunt (12 is Kerberos).',['leeuw met onkwetsbare huid · kracht','negenkoppige slang (Hydra) · slimheid','vogels met bronzen veren als projectielen','ongelofelijk snelle hinde, gewijd aan Artemis · snelheid','enorm everzwijn · kracht','stier van Poseidon · kracht','vleesetende merries van koning Diomedes','vee van het monster Geryon','stallen van Augias in één dag · slimheid','gordel van de Amazonenkoningin Hippolyte','gouden appels van de Hesperiden · slimheid','Kerberos, de driekoppige hond · kracht en slimheid'],
  'Zie de kernpunten: twaalf opdrachten met wat gevaarlijk was en of Herakles vooral kracht of slimheid nodig had. Volgorde zoals de afbeeldingen op p. 43.','Welke twaalf opdrachten moest Herakles doen?');
mk('h45a','o45','Opdracht 45a','Schrijf het bovenste woord op de zak (ΤΣΙΜΕΝΤΟ) in kleine letters.','τσιμέντο',['τσιμεντω','τζιμεντο','ταιμεντο'],'Τ = τ, Σ = σ, Ι = ι, Μ = μ, Ε = ε, Ν = ν, Τ = τ, Ο = ο.','Hoe schrijf je ΤΣΙΜΕΝΤΟ in kleine letters?');
mk('h45b','o45','Opdracht 45b','Om welk product gaat het, en onder welke merknaam wordt het verkocht?','cement, onder de naam Herakles (ΗΡΑΚΛΗΣ)',['meel, onder de naam Atlas','olijfolie, onder de naam Herakles','cement, onder de naam Athena'],'τσιμέντο = cement; ΗΡΑΚΛΗΣ = Ἡρακλῆς.','Wat zit er in de zak en wat is de merknaam?');
mk('h45d','o45','Opdracht 45d','Waarom is Herakles een goede naam voor dit product?','Cement moet sterk zijn, en Herakles is de sterkste held',['Herakles heeft huizen gebouwd','Cement komt uit Griekenland','Herakles was een god van de bouw'],'De merknaam belooft kracht.','Waarom past de naam Herakles bij cement?');

