const Z11=[
 [1,3,'Ὁ Ἀγαμέμνων τοὺς τοῦ Κάλχαντος λόγους ἀγανακτεῖ καὶ λέγει· «Ὦ Ἕλληνες, ἀκούετέ μου.','Agamemnon wordt boos over de woorden van Kalchas en zegt: "Grieken, luister naar mij.',['τοὺς τοῦ Κάλχαντος λόγους = de woorden van Kalchas','ἀγανακτεῖ = wordt boos (over)','ἀκούετέ μου = luister naar mij (imperativus mv + gen)'],'ἀκούετε is een gebiedende wijs (imperativus): luister!'],
 [3,4,'Τὴν μὲν Χρυσηΐδα ἐν τῷ οἴκῳ μοι ἔχειν ἐθέλω.','Chryseïs wil ik bij mij thuis hebben.',['τὴν Χρυσηΐδα = Chryseïs (acc)','ἐν τῷ οἴκῳ = in huis, thuis','μοι = voor mij / bij mij'],''],
 [4,6,'Εἰ δὲ δεῖ τὴν κόρην λύειν καὶ πάλιν εἰς τὸν πατέρα πέμπειν, οὕτω πράττω· σῴζειν γὰρ ὑμᾶς ἐθέλω.','Maar als het nodig is het meisje vrij te laten en terug naar haar vader te sturen, dan doe ik dat; want ik wil jullie redden.',['εἰ δεῖ = als het nodig is','λύειν = vrijlaten','πάλιν εἰς τὸν πατέρα πέμπειν = terug naar haar vader sturen','οὕτω πράττω = zo doe ik','σῴζειν ὑμᾶς = jullie redden'],''],
 [6,8,'Ἀλλ’ αὐτίκα ἄλλο τι δῶρόν μοι παρέχετε· πρέπει γὰρ τῷ ἡγεμόνι τῶν Ἑλλήνων δῶρον λαμβάνειν.»','Maar geef mij meteen een ander geschenk; want het past de leider van de Grieken een geschenk te krijgen."',['αὐτίκα = meteen','ἄλλο τι δῶρον = een ander geschenk','παρέχετε = geef (imperativus mv)','πρέπει τῷ ἡγεμόνι = het past de leider'],''],
 [9,10,'Ὁ δ’ Ἀχιλλεὺς λέγει αὐτῷ· «Ὦ Ἀγάμεμνον, μὴ ἴσθι φιλοκτέανος.','Achilles zegt tegen hem: "Agamemnon, wees niet hebzuchtig.',['λέγει αὐτῷ = zegt tegen hem','ὦ Ἀγάμεμνον = Agamemnon (vocativus)','μὴ ἴσθι = wees niet (μή + imp)','φιλοκτέανος = hebzuchtig'],'Ἀγάμεμνον is een vocativus: zo spreek je iemand aan.'],
 [10,11,'Πῶς γὰρ οἱ Ἕλληνες ἄλλο τι δῶρόν σοι παρέχειν μέλλουσιν;','Want hoe zullen de Grieken jou een ander geschenk geven?',['πῶς = hoe','σοι = (aan) jou','παρέχειν μέλλουσιν = zullen geven'],''],
 [11,12,'Οὐκέτι λάφυρα ἀνέμητά ἐστιν.','Er is geen onverdeelde buit meer.',['οὐκέτι = niet meer','λάφυρα ἀνέμητα = onverdeelde buit'],''],
 [12,13,'Ἄγε δή, νῦν μὲν τάχα πέμπε τὴν κόρην πάλιν εἰς τὸν πατέρα.','Kom op, stuur het meisje nu snel terug naar haar vader.',['ἄγε δή = kom op','τάχα = snel','πέμπε = stuur (imperativus ev)'],''],
 [13,15,'Ὡς δὲ τάχιστα τὴν Τροίαν διαφθείρομεν, δῶρά σοι τριπλάσια παρέχομεν.»','Zodra we Troje vernietigen, geven we jou driemaal zo grote geschenken."',['ὡς τάχιστα = zodra','τὴν Τροίαν διαφθείρομεν = we vernietigen Troje','δῶρα τριπλάσια = driemaal zo grote geschenken'],''],
 [16,17,'Ὁ δ’ Ἀγαμέμνων λέγει· «Ὦ Ἀχιλλεῦ, μή μ’ ἐρέθιζε· γιγνώσκω γὰρ ὅτι μοι φθονεῖς.','Agamemnon zegt: "Achilles, maak me niet kwaad; want ik weet dat je jaloers op me bent.',['ὦ Ἀχιλλεῦ = Achilles (vocativus)','μή μ’ ἐρέθιζε = maak me niet kwaad','γιγνώσκω ὅτι = ik weet dat','μοι φθονεῖς = je bent jaloers op mij (+ dat)'],'μ’ = με vóór een klinker.'],
 [18,21,'Σὺ δ’ ἐθέλεις με τὸ δῶρον ἀφαιρεῖν· οὕτως ἐγὼ μέν, ὁ τοῦ τῶν Ἑλλήνων στόλου ἡγεμών, οὐκέτι τιμὴν ἔχω, σὺ δ’ ἔτι δῶρον ἔχεις, τὴν κόρην Βρισηΐδα.','Jij wilt mij het geschenk afpakken; zo heb ik, de leider van het leger van de Grieken, geen eer meer, maar jij hebt nog een geschenk, het meisje Briseïs.',['με τὸ δῶρον ἀφαιρεῖν = mij het geschenk afpakken (acc + acc)','ὁ … ἡγεμών = de leider','οὐκέτι τιμὴν ἔχω = ik heb geen eer meer','ἔτι = nog'],''],
 [21,23,'Εἰ δ’ οὖν οἱ Ἕλληνες οὐκ ἄλλο τι δῶρόν μοι παρέχουσι, τὴν Βρισηΐδα μέλλω ἁρπάζειν.»','Als de Grieken mij dus geen ander geschenk geven, zal ik Briseïs roven."',['εἰ οὖν = als dus','μέλλω ἁρπάζειν = ik zal roven'],''],
 [24,24,'Νῦν δ’ ἀγανακτεῖ καὶ ὁ Ἀχιλλεὺς καὶ λέγει·','Nu wordt ook Achilles boos en zegt:',['καὶ ὁ Ἀχιλλεύς = ook Achilles'],''],
 [25,27,'«Ὦ κάκιστε, λέγεις ὅτι ἡγεμὼν τῶν Ἑλλήνων εἶ, ἀλλ’ οὔποτε τῆς μάχης μετέχεις· ἐλάφου γὰρ καρδίαν ἔχεις.','"Lafaard, je zegt dat je de leider van de Grieken bent, maar je neemt nooit deel aan de strijd; want je hebt het hart van een hert.',['ὦ κάκιστε = lafaard (vocativus)','λέγεις ὅτι … εἶ = je zegt dat je … bent','οὔποτε τῆς μάχης μετέχεις = je neemt nooit deel aan de strijd','ἐλάφου καρδίαν = het hart van een hert'],''],
 [27,28,'Ἐγὼ μὲν ἀεὶ ἐν τῇ μάχῃ κάμνω, σὺ δὲ μόνον οἶνον πίνεις.','Ik zwoeg altijd in de strijd, maar jij drinkt alleen wijn.',['ἐν τῇ μάχῃ κάμνω = ik zwoeg in de strijd','μόνον οἶνον πίνεις = je drinkt alleen wijn'],'ἐγὼ μὲν … σὺ δέ: ik … maar jij.'],
 [28,30,'Εἰ δὲ τὴν Βρισηΐδα ἁρπάζειν ἐθέλεις, οὐ σὲ κωλύω· ἀλλ’ οὐκέτι τῆς μάχης μετέχω.»','Als je Briseïs wilt roven, ik houd je niet tegen; maar ik neem niet meer deel aan de strijd."',['οὐ σὲ κωλύω = ik houd je niet tegen','οὐκέτι τῆς μάχης μετέχω = ik neem niet meer deel aan de strijd'],'']];
