V.leer=ORDE.filter(p=>p!=='mix');
Object.assign(V.PN,{'8t':'Tekst 8 ΑΡΓΟΝΑΥΤΑΙ','hb8':'Hulpboek les 8 · opdrachten','hb9':'Hulpboek les 9 · opdrachten','hb10':'Les 10 Het Gulden Vlies · opdrachten','epi':'Epiloog Herakles · opdrachten','t3p':'Thema 3 Troje · proloog','11w':'Les 11 · Woorden','11t':'Tekst 11 ΑΓΑΜΕΜΝΩΝ ΚΑΙ ΑΧΙΛΛΕΥΣ','hb11':'Hulpboek les 11 · opdrachten'});
V.kop='Argo · Thema 2 en 3';
